class Solution {
public:
    struct TrieNode {
        TrieNode* children[26];
        bool isEnd;
        TrieNode() : isEnd(false) {
            for (int i = 0; i < 26; i++) children[i] = nullptr;
        }
    };

    TrieNode* root;

    void insert(const string& word) {
        TrieNode* node = root;
        for (char c : word) {
            int idx = c - 'a';
            if (!node->children[idx]) {
                node->children[idx] = new TrieNode();
            }
            node = node->children[idx];
        }
        node->isEnd = true;
    }

    void setEnd(const string& word, bool val) {
        TrieNode* node = root;
        for (char c : word) {
            node = node->children[c - 'a'];
        }
        node->isEnd = val;
    }

    bool canForm(const string& word) {
        int n = word.size();
        vector<bool> dp(n + 1, false);
        dp[n] = true;
        for (int i = n - 1; i >= 0; i--) {
            TrieNode* node = root;
            for (int j = i; j < n; j++) {
                int idx = word[j] - 'a';
                if (!node->children[idx]) break;
                node = node->children[idx];
                if (node->isEnd && dp[j + 1]) {
                    dp[i] = true;
                    break;
                }
            }
        }
        return dp[0];
    }

    vector<string> findAllConcatenatedWordsInADict(vector<string>& words) {
        root = new TrieNode();
        for (const string& w : words) {
            insert(w);
        }
        vector<string> result;
        for (const string& w : words) {
            setEnd(w, false);
            if (canForm(w)) {
                result.push_back(w);
            }
            setEnd(w, true);
        }
        return result;
    }
};
